import type { CatalogItem, CatalogKind } from '../src/features/admin/catalogApi';

const shots = process.env.FINITUDE_CATALOG_E2E_SCREENSHOTS_DIR ?? '/tmp/finitude-first-use-fixed-20261014';
type Locale = 'en-US' | 'zh-Hans';
let locale: Locale = 'en-US';
// One desktop English and one mobile Chinese pass cover both layout and localization without the full cross product.
const localizedViewports = [{ width: 1280, locale: 'en-US' }, { width: 390, locale: 'zh-Hans' }] as const;

/** A review's automatic lookup that found no release: nothing applied and nothing to answer. */
const noReleaseLookup = (): ReviewLookupResponse['lookup'] => ({ ...reviewLookupResponse().lookup!, outcome: 'noRelease', candidates: [], groups: [], preselection: null, disclosure: null,
  applied: null, needsAnswer: { tie: false, conflicts: [] }, blocking: false });

/** Use the shipped localization contract, including counts and names, for real language-switch coverage. */
function label(key: keyof typeof english, parameters: Record<string, string | number> = {}) {
  return (locale === 'zh-Hans' ? chinese[key] : english[key]).replace(/\{([^}]+)\}/g, (token, name: string) => String(parameters[name] ?? token));
}
/** A message with plural or select arguments, formatted as the app formats the shipped catalog (label() only fills plain ones). */
function message(key: keyof typeof english, parameters: Record<string, string | number> = {}) {
  return String(new IntlMessageFormat(locale === 'zh-Hans' ? chinese[key] : english[key], locale, undefined, { ignoreTag: true }).format(parameters));
}
/** A message as a pattern whose `elapsed` variable is any "m:ss" time, as the time moves while a run is shown. */
const elapsedPattern = (key: keyof typeof english) => {
  const text = message(key, { elapsed: 'ELAPSED' }).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(text.replace('ELAPSED', '\\d+:\\d{2}'));
};
/** The review's refined status: its sentences joined as the summary joins them (none after a Chinese full stop). */
const refinedStatus = (...sentences: string[]) => sentences.reduce((text, next) => `${text}${text.endsWith('。') ? '' : ' '}${next}`);
const possiblePairing = () => refinedStatus(message('admin.catalog_review.lookup_possible_found', { count: 1, title: 'Synthetic Live Album 2' }), label('admin.catalog_review.lookup_cause_pairing'));
test.beforeEach(() => { locale = 'en-US'; });
type Write = { path: string; method: string; body: Record<string, unknown> };
const privateCoverPath = `/api/admin/v1/catalog/album/${albumId}/artwork`;
// Self-authored artwork becomes actual decoded PNG bytes; the visual gate cannot pass on a placeholder or a broken img.
const coverSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="640" height="640" viewBox="0 0 640 640">
  <rect width="640" height="640" fill="#122c3c"/><rect x="28" y="28" width="584" height="584" fill="#f3cda0"/>
  <path d="M28 450L310 112 612 420V612H28Z" fill="#ca5e4b"/><path d="M28 515L275 252 490 612H28Z" fill="#213c4c"/>
  <circle cx="495" cy="145" r="57" fill="#e59759"/><path d="M52 84H588M52 96H588" stroke="#213c4c" stroke-width="3"/>
  <text x="52" y="70" fill="#213c4c" font-family="sans-serif" font-size="25" letter-spacing="5">FIELD RECORDINGS</text>
  <text x="52" y="571" fill="#f3cda0" font-family="sans-serif" font-size="43" letter-spacing="4">FIRST LIGHT</text>
  <text x="54" y="596" fill="#f3cda0" font-family="sans-serif" font-size="13" letter-spacing="3">SYNTHETIC COVER FIXTURE</text>
</svg>`;
const coverPalettes = [['#122c3c', '#f3cda0', '#ca5e4b', '#213c4c', '#e59759'],
  ['#33273a', '#edcbdc', '#a36793', '#56344f', '#e6a989'],
  ['#25332b', '#e3d9bd', '#82916a', '#394b40', '#d7ac6d'],
  ['#293242', '#d5e1e3', '#628eac', '#334a65', '#9bb8c0']];
const privateCoverFixtures = coverPalettes.map(palette => sharp(Buffer.from(coverSvg.replace(/#[a-f0-9]{6}/g,
  color => palette[coverPalettes[0].indexOf(color)] ?? color))).png().toBuffer());
/**
 * `lookupAvailable` false: the server runs no metadata lookup, so the Album page creates a completion for manual editing;
 * `ineligible`: why the Album cannot have a completion (none by default).
 */
type CatalogPresentation = { title?: string; cover?: 'ready' | 'missing' | 'failed'; additionalAlbums?: number; albumTracks?: CatalogAlbumTracks; lookupAvailable?: boolean;
  ineligible?: string };
const remainingCatalogKinds = ['artist', 'audioTrack', 'organization'] as const;
type RemainingCatalogKind = typeof remainingCatalogKinds[number];

/** Different catalog kinds retain their real field contracts rather than posing as Albums. */
function remainingCatalogItems(kind: RemainingCatalogKind): CatalogItem[] {
  const ids = { artist: '5678', audioTrack: '9abc', organization: 'def0' }[kind];
  return Array.from(ids, (value, index): CatalogItem => {
    const id = value.repeat(24), visibility = index % 2 ? 'hidden' as const : 'public' as const;
    const name = index === 0 ? `Synthetic ${kind} — 夜间录音与海岸回声 / Collected histories and a long name for careful administration`
      : kind === 'organization' && index === 1 ? '𠮷祥 Archive · Synthetic organization'
      : `Synthetic ${kind} ${index + 1} · ${['静默回声', '夜间录音', '无声海岸'][index - 1]}`;
    const common = { id, revision: catalogAlbum().revision, visibility, effectiveVisibility: visibility,
      coverUrl: kind === 'organization' ? null : `/api/admin/v1/catalog/${kind}/${id}/artwork`, mediaUrl: null,
      capabilities: { editing: true, visibility: true } };
    if (kind === 'artist') return { ...common, kind, fields: { name, bio: 'Synthetic biography. 私有目录中的艺术家介绍。', birthDate: { year: 1987, month: null, day: null }, musicBrainzId: null } };
    if (kind === 'organization') return { ...common, kind, fields: { name, description: 'Synthetic organization. 保存与发行录音的机构。', organizationType: 'archive', musicBrainzId: null } };
    return { ...common, kind, fields: { title: name, releaseDate: { year: 2023 + index, month: null, day: null }, credits: null, attributionStatus: 'unknown', discNumber: null, trackNumber: index + 1 } };
  });
}

/** Only fabricated catalog data and route responses are used; no provider, storage or account is contacted. */
async function setup(page: Page, administrator = true, initialReleaseDate: { year: number; month: number | null; day: number | null } | null = null, presentation: CatalogPresentation = {}) {
  let album = catalogAlbum(), review = catalogReview(), created = false, denied = false, finishAnalysis = false;
  // A discarded review leaves a tombstone: every read of it is then refused as discarded until a creation stores another.
  let discarded = false;
  let artworkFailed = presentation.cover === 'failed';
  album.fields.releaseDate = initialReleaseDate;
  album.fields.title = presentation.title ?? album.fields.title;
  album.coverUrl = presentation.cover === 'missing' ? null : privateCoverPath;
  const extraAlbums = Array.from({ length: presentation.additionalAlbums ?? 0 }, (_, index) => {
    const id = (index + 2).toString(16).repeat(24), visibility = index % 2 ? 'hidden' as const : 'public' as const;
    return { ...catalogAlbum(), id, visibility, effectiveVisibility: visibility, coverUrl: `/api/admin/v1/catalog/album/${id}/artwork`,
      fields: { ...catalogAlbum().fields, title: `Synthetic Album ${index + 2} · ${['夜间录音', '静默回声', '无声海岸'][index] ?? 'Collected recordings'}`,
        releaseDate: { year: 2023 + index, month: null, day: null } } };
  });
  const otherItems = remainingCatalogKinds.flatMap(kind => remainingCatalogItems(kind));
  // The Album's read-only members; each listed member also opens as its own catalog page. A confirmed clear removes the expected
  // tracklist from later reads, and an applied completion writes the Credits and tracklist it selected.
  let albumTracks = presentation.albumTracks ?? catalogAlbumTracks();
  const memberItems = new Map<string, CatalogItem>(albumTracks.tracks.flatMap(track => 'title' in track ? [[track.id, { ...catalogAlbum(), kind: 'audioTrack' as const, id: track.id,
    fields: { ...catalogAlbum().fields, title: track.title, discNumber: track.discNumber, trackNumber: track.trackNumber } }]] : []));
  // The Artists and Organizations applied Credits name, read back by their catalog pages.
  const credited = new Map<string, CatalogItem>();
  const lookupAvailable = presentation.lookupAvailable ?? true;
  const reads: string[] = [], writes: Write[] = [];
  const headers = { 'X-Finitude-Account-Viewer': viewer, 'Cache-Control': 'no-store' };
  await page.route('**/*', route => new URL(route.request().url()).hostname === '127.0.0.1' ? route.continue() : route.abort('blockedbyclient'));
  await page.route('**/auth/browser/session', route => route.fulfill({ json: { user: { ...session.user, role: administrator ? 'admin' : 'user' } } }));
  await page.route('**/api/listener/v1/capabilities', route => route.fulfill({ json: { playlists: false } }));
  await page.route('**/api/listener/v1/personalization-capabilities', route => route.fulfill({ json: { contractVersion: 1, deterministicDiscovery: false, artistFollows: false } }));
  await page.route('**/api/listener/v1/home', route => route.fulfill({ json: { title: 'Synthetic Home', sections: [] }, headers }));
  await page.route('**/content/me/playlists?limit=50', route => route.fulfill({ json: { items: [], nextCursor: null }, headers }));
  const receipt = (body: Record<string, unknown>, kind: CatalogReview['receipts'][number]['kind']) => {
    const value = { operationId: String(body.operationId), kind, revision: review.revision };
    review.receipts.push(value);
    return { item: review, receipt: value };
  };
  // The review's metadata lookup: its view (none before a run), the response a submitted run completes with, whether the next
  // read still sees that run queued, and the identity rows. Lookup and decision receipts are answered, never listed in the detail.
  let lookup: ReviewLookupResponse['lookup'] = null, completion: ReviewLookupResponse['lookup'] = reviewLookupResponse().lookup, queuedReads = 0;
  let identities: ReviewIdentityResponse = reviewIdentityResponse();
  // The pairing panel's read of a candidate (none answers it as not found) and how many choices still fail as unavailable.
  let pairingRead: ((item: CatalogReview) => object) | null = null, failChooses = 0;
  /** The identity read where nothing differs from what the review captured: no identity row or Credit change. */
  const unchanged = (value: ReviewIdentityResponse): ReviewIdentityResponse => ({ ...value, selection: { lists: [], label: false }, keptTracklist: null, identities: [], label: null,
    candidates: { items: [], unavailable: [] }, preselections: [], musicBrainzIds: [], album: null, members: [] });
  // A seeded flow's server side: the view a save re-ranks the run to (none keeps it), and what choosing a release writes (none:
  // the release of `completion` applied as it stands).
  let reranking: ((draft: CatalogReview['draft'], current: ReviewLookupResponse['lookup']) => ReviewLookupResponse['lookup'] | undefined) | null = null;
  let choosing: ((key: string | null, current: NonNullable<ReviewLookupResponse['lookup']>, item: CatalogReview) =>
    { lookup: ReviewLookupResponse['lookup']; draft?: CatalogReview['draft'] } | undefined) | null = null;
  const lookupReceipt = (body: Record<string, unknown>, kind: CatalogReview['receipts'][number]['kind']) => {
    review = { ...review, revision: review.revision + 1, updatedAt: new Date(Date.parse(review.updatedAt) + 60_000).toISOString() };
    return { item: review, receipt: { operationId: String(body.operationId), kind, revision: review.revision } };
  };
  const queue = (input: NonNullable<ReviewLookupResponse['lookup']>['input']) => {
    const run = (lookup?.run ?? 0) + 1;
    completion = { ...completion!, run, input, applied: completion!.applied && { ...completion!.applied, run } };
    lookup = { ...completion, state: 'queued', outcome: null, candidates: [], groups: [], preselection: null, disclosure: null, applied: lookup?.applied ?? null,
      needsAnswer: { tie: false, conflicts: lookup?.needsAnswer.conflicts ?? [] }, blocking: true };
    queuedReads = 1;
  };
  await page.route('**/api/admin/v1/**', async route => {
    const request = route.request(), path = new URL(request.url()).pathname, method = request.method();
    if (method === 'GET') reads.push(path);
    const coverIndex = [album, ...extraAlbums, ...otherItems].findIndex(item => item.coverUrl === path);
    if (coverIndex >= 0) {
      expect(method).toBe('GET'); expect(new URL(request.url()).searchParams.get('viewer')).toBe(viewer);
      if (denied || artworkFailed) return route.fulfill({ status: denied ? 403 : 404, body: '', headers });
      return route.fulfill({ contentType: 'image/png', body: await privateCoverFixtures[coverIndex % privateCoverFixtures.length], headers });
    }
    expect(request.headers()['x-finitude-account-viewer']).toBe(viewer);
    if (denied) return route.fulfill({ status: 403, json: { code: 'ADMIN_REQUIRED' }, headers });
    if (path.endsWith('/capabilities')) return route.fulfill({ json: { ...capabilities, catalog: { editing: true, visibility: true },
      localMp3Conversion: { enabled: true, readSources: true, replace: true, preset: 'mp3-320', maxFiles: 100 } }, headers });
    if (path === '/api/admin/v1/imports') return route.fulfill({ json: { items: [], counts: { all: 0, analyzing: 0, awaitingReview: 0, needsAttention: 0, completed: 0 }, nextCursor: null }, headers });
    if (path === '/api/admin/v1/catalog/album') return route.fulfill({ json: { items: [album, ...extraAlbums], nextCursor: null }, headers });
    for (const kind of remainingCatalogKinds) {
      if (path === `/api/admin/v1/catalog/${kind}`) {
        expect(method).toBe('GET');
        return route.fulfill({ json: { items: otherItems.filter(item => item.kind === kind), nextCursor: null }, headers });
      }
    }
    const otherItem = otherItems.find(item => path === `/api/admin/v1/catalog/${item.kind}/${item.id}` || path === `/api/admin/v1/catalog/${item.kind}/${item.id}/cover-operations`);
    if (otherItem) {
      expect(method).toBe('GET');
      return route.fulfill({ json: path.endsWith('/cover-operations') ? { items: [] } : { item: otherItem }, headers });
    }
    if (path === `/api/admin/v1/catalog/album/${albumId}/cover-operations`) return route.fulfill({ json: { items: [] }, headers });
    if (path === `/api/admin/v1/catalog/album/${albumId}/tracks`) { expect(method).toBe('GET'); return route.fulfill({ json: albumTracks, headers }); }
    const member = /^\/api\/admin\/v1\/catalog\/audioTrack\/([0-9a-f]{24})(\/cover-operations)?$/.exec(path);
    if (member && memberItems.has(member[1])) {
      expect(method).toBe('GET');
      return route.fulfill({ json: member[2] ? { items: [] } : { item: memberItems.get(member[1]) }, headers });
    }
    const credit = /^\/api\/admin\/v1\/catalog\/(?:artist|organization)\/([0-9a-f]{24})$/.exec(path);
    if (credit && credited.has(credit[1])) { expect(method).toBe('GET'); return route.fulfill({ json: { item: credited.get(credit[1]) }, headers }); }
    if (path === '/api/admin/v1/catalog-reviews/eligibility') {
      // The Album page's action: the open completion while it is unapplied and its source current.
      expect([method, new URL(request.url()).searchParams.get('albumId')]).toEqual(['GET', albumId]);
      const reason = presentation.ineligible ?? null;
      return route.fulfill({ json: { eligible: reason === null, reason, openReviewId: created && review.state === 'reviewing' && review.sourceStatus === 'current' ? reviewId : null,
        lookupAvailable }, headers });
    }
    if (path === `/api/admin/v1/catalog/album/${albumId}`) {
      if (method === 'GET') return route.fulfill({ json: { item: album }, headers });
      expect(method).toBe('PATCH');
      const body = request.postDataJSON(); writes.push({ path, method, body });
      expect(body.expectedRevision).toBe(album.revision);
      if (body.visibility !== undefined) expect(['public', 'hidden']).toContain(body.visibility);
      if (body.clearExpectedTracklist !== undefined) {
        // The Web sends a clear alone, as one explicit true.
        expect(Object.keys(body).sort()).toEqual(['clearExpectedTracklist', 'expectedRevision', 'operationId']);
        expect(body.clearExpectedTracklist).toBe(true);
        albumTracks = { ...albumTracks, expected: null };
      }
      album = { ...album, revision: `cr_${'b'.repeat(43)}`, visibility: body.visibility ?? album.visibility,
        effectiveVisibility: body.visibility ?? album.effectiveVisibility, fields: { ...album.fields, ...body.fields } };
      return route.fulfill({ json: { item: album, receipt: { operationId: body.operationId } }, headers });
    }
    if (path === '/api/admin/v1/catalog-reviews') {
      if (method === 'GET') {
        const counts = { all: created ? 1 : 0, analyzing: created && ['queued', 'running'].includes(review.analysis.state) ? 1 : 0,
          awaitingReview: created && review.state === 'reviewing' ? 1 : 0, needsAttention: 0, completed: created && review.state === 'applied' ? 1 : 0 };
        return route.fulfill({ json: { items: created ? [{ id: review.id, revision: review.revision, createdAt: review.createdAt, updatedAt: review.updatedAt, startedByMe: review.startedByMe,
          state: review.state, analysis: review.analysis, albumId, albumTitle: review.source.album.title, title: review.source.album.title, pendingSuggestions: review.suggestions.filter(value => value.decision === 'pending').length }] : [], counts, nextCursor: null }, headers });
      }
      expect(method).toBe('POST');
      const body = request.postDataJSON(); writes.push({ path, method, body });
      expect(body).toMatchObject({ albumId, expectedRevision: album.revision });
      // Where lookup runs, the server converts the new review for lookup (format 3, one revision without a receipt) and queues its
      // automatic catalog run; otherwise it stays a review for manual editing.
      const fixture = lookupAvailable ? capturedCatalogReview() : catalogReview();
      review = { ...fixture, revision: lookupAvailable ? 2 : 1, source: { ...fixture.source, album: { ...fixture.source.album, title: album.fields.title, revision: album.revision } },
        draft: { ...fixture.draft, album: { ...fixture.draft.album, title: album.fields.title, ...(lookupAvailable ? { expectedTracklist: null } : {}) } },
        analysis: { ...fixture.analysis, state: 'idle', generation: 0, operationId: null, completedChunks: 0, totalChunks: 0, attemptsUsed: 0 }, suggestions: [] };
      created = true; discarded = false;
      if (lookupAvailable) queue({ trigger: 'catalog', submitted: null });
      const value = { operationId: String(body.operationId), kind: 'create' as const, revision: 1 };
      review.receipts = [value];
      return route.fulfill({ status: 201, json: { item: review, receipt: value }, headers });
    }
    if (discarded && path.startsWith(`/api/admin/v1/catalog-reviews/${reviewId}`)) return route.fulfill({ status: 404, json: { code: 'ADMIN_CATALOG_REVIEW_DISCARDED' }, headers });
    if (path === `/api/admin/v1/catalog-reviews/${reviewId}`) {
      if (method === 'GET') {
        if (finishAnalysis && review.analysis.state === 'queued') {
          review.analysis = { ...review.analysis, state: 'complete', completedChunks: 2, totalChunks: 2, attemptsUsed: 2 };
          review.suggestions = catalogReview().suggestions.map(value => value.id === titleSuggestionId ? { ...value, baseline: review.source.album.title } : value);
          review.revision++;
        }
        return route.fulfill({ json: { item: review, receipt: null }, headers });
      }
      expect(method).toBe('PATCH');
      const body = request.postDataJSON(); writes.push({ path, method, body });
      expect(body.expectedRevision).toBe(review.revision);
      // A review save sends only changed values, each with its base; the server writes each value at its path.
      expect(body).not.toHaveProperty('draft');
      const draft = structuredClone(review.draft);
      for (const { path: valuePath, value } of body.changes as ReviewDraftChange[]) {
        const [scope, first, second] = valuePath.split('.');
        if (scope === 'album') (draft.album as Record<string, unknown>)[first] = value;
        else (draft.tracks.find(track => track.slotId === first) as Record<string, unknown>)[second] = value;
      }
      review = { ...review, revision: review.revision + 1, draft };
      // The server re-ranks a completed run in the save's own transaction.
      const reranked = reranking?.(draft, lookup);
      if (reranked) lookup = completion = reranked;
      return route.fulfill({ json: receipt(body, 'edit'), headers });
    }
    if (path === `/api/admin/v1/catalog-reviews/${reviewId}/lookup` && method === 'GET') {
      // The first read after a submission sees its run queued; the next completes it, writing its values at the same revision and the
      // next value revision.
      if (lookup?.state === 'queued' && !queuedReads--) {
        lookup = completion;
        if (completion?.applied) review = { ...reviewAfterLookup(review), updatedAt: new Date(Date.parse(review.updatedAt) + 1_000).toISOString() };
      }
      const active = Boolean(lookup && ['queued', 'running', 'retrying'].includes(lookup.state));
      return route.fulfill({ json: { lookup, revision: review.revision, valueRevision: review.valueRevision, summary: { waiting: { lookup: active, analysis: ['queued', 'running'].includes(review.analysis.state) },
        needsAnswer: { tie: lookup?.needsAnswer.tie ?? false, conflicts: lookup?.needsAnswer.conflicts ?? [] }, lookupAvailable } }, headers });
    }
    const pairing = new RegExp(`^/api/admin/v1/catalog-reviews/${reviewId}/lookup/candidates/([^/]+)/pairing$`).exec(path);
    if (pairing) {
      // A JSON read of the review's current revision; the viewer is named in its header, never in the query.
      expect([method, new URL(request.url()).search]).toEqual(['GET', '']);
      return route.fulfill(pairingRead ? { json: { ...pairingRead(review), revision: review.revision }, headers } : { status: 404, json: { code: 'ADMIN_CATALOG_REVIEW_NOT_FOUND' }, headers });
    }
    if (path === `/api/admin/v1/catalog-reviews/${reviewId}/candidates`) {
      expect(method).toBe('GET');
      // Without an applied release nothing differs from what the review captured: no identity row or Credit change.
      return route.fulfill({ json: { ...(lookup?.applied ? identities : unchanged(identities)), revision: review.revision, valueRevision: review.valueRevision }, headers });
    }
    if (path.startsWith(`/api/admin/v1/catalog-reviews/${reviewId}/`) && method === 'POST') {
      const body = request.postDataJSON(); writes.push({ path, method, body });
      expect(body.expectedRevision).toBe(review.revision);
      if (path.endsWith('/discard')) {
        // The server keeps only a tombstone: the review leaves the queue and the Album page, and its lookup run ends.
        expect(Object.keys(body).sort()).toEqual(['expectedRevision', 'operationId']);
        created = false; discarded = true; lookup = null;
        return route.fulfill({ json: { discarded: { id: reviewId, albumId }, receipt: { operationId: String(body.operationId), kind: 'discard', revision: review.revision + 1 } }, headers });
      }
      if (path.endsWith('/analyze')) {
        review = { ...review, revision: review.revision + 1, analysis: { ...review.analysis, state: 'queued', generation: 1, operationId: body.operationId } };
        return route.fulfill({ status: 202, json: receipt(body, 'analyze'), headers });
      }
      if (path.endsWith('/adopt') && !(body.selectedIds as string[]).length) {
        // Keep current rejects the listed suggestions and changes no value.
        review = { ...review, revision: review.revision + 1, suggestions: review.suggestions.map(value => (body.rejectIds as string[]).includes(value.id) ? { ...value, decision: 'rejected' } : value) };
        return route.fulfill({ json: receipt(body, 'adopt'), headers });
      }
      if (path.endsWith('/adopt')) {
        expect(body.selectedIds).toEqual([titleSuggestionId]); expect(body.rejectIds).toEqual([]);
        const selected = review.suggestions.find(value => value.id === titleSuggestionId)!;
        review = { ...review, revision: review.revision + 1, draft: { ...review.draft, album: { ...review.draft.album, title: String(selected.value) } },
          suggestions: review.suggestions.map(value => value.id === titleSuggestionId ? { ...value, decision: 'accepted' } : value) };
        return route.fulfill({ json: receipt(body, 'adopt'), headers });
      }
      if (path.endsWith('/lookup')) {
        // `artist` is sent only when the Artist field is not empty, and then trimmed.
        expect(Object.keys(body).sort()).toEqual(['expectedRevision', 'kind', 'operationId', 'text', ...('artist' in body ? ['artist'] : [])].sort());
        if ('artist' in body) expect(typeof body.artist === 'string' && body.artist.length > 0 && body.artist === body.artist.trim()).toBe(true);
        queue({ trigger: 'submitted', submitted: { kind: body.kind as 'album' | 'song', text: String(body.text), ...(typeof body.artist === 'string' ? { artist: body.artist } : {}) } });
        return route.fulfill({ status: 202, json: lookupReceipt(body, 'lookup'), headers });
      }
      if (path.endsWith('/lookup/retry')) { queue(lookup!.input); return route.fulfill({ status: 202, json: lookupReceipt(body, 'lookup-retry'), headers }); }
      if (path.endsWith('/lookup/choose')) {
        expect(body.run).toBe(lookup!.run);
        if (failChooses > 0) { failChooses--; return route.fulfill({ status: 503, json: { code: 'ADMIN_CATALOG_REVIEW_UNAVAILABLE' }, headers }); }
        const key = body.candidateKey as string | null, chosen = choosing?.(key, lookup!, review);
        // A choice that writes values moves the value revision; the receipt moves the revision.
        if (chosen) {
          lookup = chosen.lookup;
          if (chosen.draft) review = { ...review, draft: chosen.draft, valueRevision: review.valueRevision + 1 };
        } else lookup = { ...lookup!, applied: { ...completion!.applied!, candidateKey: key, choice: key ? 'chosen' : 'none', basis: key ? 'chosen' : null } };
        return route.fulfill({ json: lookupReceipt(body, 'lookup-choose'), headers });
      }
      if (path.endsWith('/lookup/resolve')) {
        // Each answer is made against the saved value; using the lookup value writes it into the review's draft and, as the server
        // stores it, lists its path among the applied values too.
        const answers = body.answers as Array<{ path: string; answer: 'mine' | 'lookup'; base: unknown }>, draft = structuredClone(review.draft);
        for (const answer of answers) {
          const conflict = lookup!.applied!.conflicts.find(item => item.path === answer.path)!, [scope, first, second] = answer.path.split('.');
          const holder = (scope === 'album' ? draft.album : draft.tracks.find(track => track.slotId === first)!) as Record<string, unknown>;
          expect(answer.base).toEqual(holder[scope === 'album' ? first : second] ?? null);
          if (answer.answer === 'lookup') holder[scope === 'album' ? first : second] = conflict.lookup;
        }
        review = { ...review, draft };
        const used = answers.filter(answer => answer.answer === 'lookup' && !lookup!.applied!.values.some(value => value.path === answer.path))
          .map(answer => ({ path: answer.path, slotId: answer.path.startsWith('tracks.') ? answer.path.split('.')[1] : null }));
        lookup = { ...lookup!, applied: { ...lookup!.applied!, values: [...lookup!.applied!.values, ...used],
          conflicts: lookup!.applied!.conflicts.map(item => ({ ...item, answer: answers.find(answer => answer.path === item.path)?.answer ?? item.answer })) },
          needsAnswer: { ...lookup!.needsAnswer, conflicts: lookup!.needsAnswer.conflicts.filter(item => !answers.some(answer => answer.path === item)) } };
        return route.fulfill({ json: lookupReceipt(body, 'lookup-resolve'), headers });
      }
      if (path.endsWith('/decisions')) {
        const decisions = body.decisions as ReviewDecisionItem[];
        identities = { ...identities, identities: identities.identities.map(row => {
          const decision = decisions.find(item => item.identity === row.id);
          return decision ? { ...row, decision: { ...decision, boundMusicBrainzId: row.musicBrainzId }, needsAnswer: false } : { ...row, decision: null };
        }) };
        return route.fulfill({ json: lookupReceipt(body, 'decisions'), headers });
      }
      expect(path.endsWith('/apply')).toBe(true);
      // Each test asserts its own selected fields through api.writes; the mocked Album takes a selected title, date, Artist entries and
      // expected tracklist, and each selected member its new Credits, documented.
      expect(review.sourceStatus).toBe('current');
      const fields = body.fields as ReviewField[], selected = (name: ReviewField['field']) => fields.some(value => value.scope === 'album' && value.field === name);
      const recordOf = (view: ReviewIdentityResponse['members'][number]['next'][number], order: number) => {
        // A record the apply creates takes an ID derived from its identity (the label's is fixed).
        const id = view.subjectId ?? view.identity?.replace(/-/g, '').slice(-24) ?? 'ab'.repeat(12);
        credited.set(id, view.subjectType === 'artist' ? { ...catalogAlbum(), kind: 'artist', id, fields: { name: view.name, bio: '', birthDate: null, musicBrainzId: null } }
          : { ...catalogAlbum(), kind: 'organization', id, coverUrl: null, fields: { name: view.name, description: '', organizationType: 'label', musicBrainzId: null } });
        return { creditId: view.creditId ?? `review_credit_${order}_${id.slice(-6)}`, subjectType: view.subjectType, subjectId: id, role: view.role, order, ...(view.joinPhrase ? { joinPhrase: view.joinPhrase } : {}) };
      };
      album = { ...album, revision: `cr_${'c'.repeat(43)}`, fields: { ...album.fields, ...(selected('title') ? { title: review.draft.album.title } : {}),
        ...(selected('releaseDate') ? { releaseDate: review.draft.album.releaseDate } : {}),
        ...(selected('artists') && identities.album ? { credits: identities.album.next.map(recordOf), attributionStatus: 'documented' as const } : {}) } };
      for (const slot of (body.memberCredits ?? []) as string[]) {
        const line = identities.members.find(value => value.slotId === slot), id = review.source.tracks.find(track => track.slotId === slot)!.id, item = memberItems.get(id);
        if (line && item && item.kind === 'audioTrack') memberItems.set(id, { ...item, fields: { ...item.fields, credits: line.next.map(recordOf), attributionStatus: 'documented' } });
      }
      const numbers = new Map(review.source.tracks.map(track => {
        const saved = review.draft.tracks.find(value => value.slotId === track.slotId)!, chosen = (name: 'discNumber' | 'trackNumber') => fields.some(value => value.slotId === track.slotId && value.field === name);
        return [track.id, { discNumber: chosen('discNumber') ? saved.discNumber : track.discNumber ?? null, trackNumber: chosen('trackNumber') ? saved.trackNumber : track.trackNumber }];
      }));
      albumTracks = { ...albumTracks, tracks: albumTracks.tracks.map(track => 'title' in track && numbers.has(track.id) ? { ...track, ...numbers.get(track.id)! } : track) };
      for (const [id, value] of numbers) { const item = memberItems.get(id); if (item?.kind === 'audioTrack') memberItems.set(id, { ...item, fields: { ...item.fields, ...value } }); }
      const rows = review.draft.album.expectedTracklist;
      if (selected('expectedTracklist') && rows) {
        const at = (row: { discNumber: number; trackNumber: number }) => [...numbers].filter(([, value]) => value.trackNumber === row.trackNumber && (value.discNumber ?? 1) === row.discNumber).map(([id]) => id);
        albumTracks = { ...albumTracks, expected: { source: 'musicbrainz', appliedAt: '2026-10-14T00:00:00.000Z', rows: rows.map(row => ({ ...row, memberIds: at(row) })),
          outsideMemberIds: [...numbers.keys()].filter(id => !rows.some(row => at(row).includes(id))) } };
      }
      review = { ...review, revision: review.revision + 1, state: 'applied', capabilities: { analysis: false, apply: false },
        applied: { operationId: body.operationId, at: '2026-10-14T00:00:00.000Z', fields: body.fields } };
      return route.fulfill({ json: receipt(body, 'apply'), headers });
    }
    if (method === 'GET' && /^\/api\/admin\/v1\/catalog\/audioTrack\/[0-9a-f]{24}\/motion-preview$/.test(path)) {
      // Motion previews default off, so the editor's preview panel renders nothing.
      return route.fulfill({ status: 404, json: { code: 'ADMIN_MOTION_PREVIEW_DISABLED' }, headers });
    }
    throw new Error(`Unexpected synthetic administrator request: ${method} ${path}`);
  });
  return { reads, writes, album: () => album, review: () => review, finish: () => { finishAnalysis = true; }, revoke: () => { denied = true; }, recoverArtwork: () => { artworkFailed = false; },
    ready: () => { created = true; }, changeSource: (reason: 'metadata' | 'media') => {
      if (reason === 'metadata') album = { ...album, revision: `cr_${'d'.repeat(43)}`, fields: { ...album.fields, title: 'Externally renamed Album' } };
      review = { ...review, sourceStatus: 'changed', capabilities: { ...review.capabilities, apply: false } };
    }, externalDraft: () => { review = { ...review, revision: review.revision + 1, draft: { ...review.draft, album: { ...review.draft.album, title: 'Another saved review value' } } }; },
    /** A completed lookup already applied to the review, as `response` shows it. */
    looked: (response: ReviewLookupResponse) => { lookup = response.lookup; completion = response.lookup; review = reviewAfterLookup(review); },
    /** What the next queued run completes with (by default the applied release of reviewLookupResponse). */
    completeWith: (value: ReviewLookupResponse['lookup']) => { completion = value; },
    /**
     * A created review and its lookup view as the server holds them, read as they are (a queued view stays queued); its identity
     * read lists no row or Credit change.
     */
    seed: (item: CatalogReview, view: ReviewLookupResponse['lookup']) => { review = item; lookup = completion = view; created = true; identities = unchanged(identities); },
    /** What a save re-ranks the run to, from the saved draft and the current view; a returned view replaces it. */
    rerank: (value: typeof reranking) => { reranking = value; },
    /** What choosing a release writes: the view to show and the draft, if values changed; none applies `completion`'s release. */
    choose: (value: typeof choosing) => { choosing = value; },
    /** What the pairing panel's read answers for the review as it stands (its revision is the review's); none answers not found. */
    pairing: (value: typeof pairingRead) => { pairingRead = value; },
    /** The next choice fails as unavailable, its outcome unknown, and changes nothing. */
    failNextChoose: () => { failChooses++; },
    lookup: () => lookup, identities: () => identities, member: (id: string) => memberItems.get(id)
  };
}

async function enter(page: Page, path: string) {
  await page.goto(path);
  if (locale === 'zh-Hans') {
    await page.getByRole('button', { name: english['language.button.change'].replace('{language}', 'English (United States)'), exact: true }).click();
    await page.getByRole('dialog', { name: english['language.dialog.title'] }).getByRole('radio', { name: '简体中文', exact: true }).click();
    await expect(page.locator('html')).toHaveAttribute('lang', 'zh-Hans');
  }
  await expectStandaloneAdministration(page, 'user');
  await page.getByRole('button', { name: label('admin.view.switch_admin'), exact: true }).click();
  await expectStandaloneAdministration(page, 'admin');
}

/** A protected management route never exposes listener chrome, even before entering Admin view. */
async function expectStandaloneAdministration(page: Page, view?: 'admin' | 'user') {
  await expect(page.locator('main')).toHaveCount(1);
  await expect(page.getByRole('main')).toHaveCount(1);
  await expect(page.getByRole('main')).toBeVisible();
  for (const [role, key] of [
    ['navigation', 'shell.nav.primary_label'], ['search', 'shell.search.global_label'],
    ['searchbox', 'shell.search.field_label'], ['complementary', 'shell.sidebar.label'],
    ['complementary', 'shell.now_playing.details_label'], ['region', 'player.region.label'],
    ['group', 'player.controls.label']
  ] as const) await expect(page.getByRole(role, { name: label(key), exact: true })).toHaveCount(0);
  await expect(page.locator('#library-sidebar')).toBeHidden();
  await expect(page.locator('#now-playing-aside')).toBeHidden();
  await expect(page.getByRole('region', { name: label('player.region.label'), exact: true, includeHidden: true })).toBeHidden();
  if (view) await expect(page.getByRole('button', { name: label(view === 'admin' ? 'admin.view.current_admin' : 'admin.view.current_user'), exact: true })).toBeVisible();
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth && document.body.scrollWidth <= innerWidth)).toBe(true);
}
test.afterEach(async ({ page }, result) => {
  if (result.status === 'passed' && new URL(page.url()).pathname.startsWith('/finitude/admin')) await expectStandaloneAdministration(page);
});
async function capture(page: Page, name: string, width: number, fullPage = true, top = true) {
  await mkdir(`${shots}/${locale}`, { recursive: true });
  await expect(page.getByRole('status').filter({ hasText: /^(Loading…|加载中…)$/ })).toHaveCount(0);
  if (top) await resetMainScroll(page);
  if (name === '05-review-draft' || name === '16-hundred-track-first-screen') {
    await saveDraftGeometry(page, name, width);
  }
  await page.screenshot({ path: `${shots}/${locale}/${name}-${width}.png`, fullPage, animations: 'disabled' });
}
async function resetMainScroll(page: Page) {
  await page.getByRole('main').evaluate(element => { element.scrollTop = 0; });
}

/** Record actual scroll and text bounds alongside first-screen screenshots for reviewable layout evidence. */
async function saveDraftGeometry(page: Page, name: string, width: number) {
  const main = await page.getByRole('main').evaluate(element => {
    const rect = element.getBoundingClientRect();
    return { x: rect.x, y: rect.y, width: rect.width, height: rect.height, scrollTop: element.scrollTop, scrollHeight: element.scrollHeight, clientHeight: element.clientHeight };
  });
  const controls: Record<string, unknown> = {};
  for (const [control, key] of [['start', 'admin.catalog_review.analysis_confirm'], ['refresh', 'admin.common.refresh'], ['save', 'admin.catalog_review.save_draft']] as const) {
    controls[control] = await page.getByRole('button', { name: label(key), exact: true }).evaluate(element => {
      const rect = element.getBoundingClientRect(), range = document.createRange();
      range.selectNodeContents(element);
      return { text: element.textContent, x: rect.x, y: rect.y, width: rect.width, height: rect.height,
        clientWidth: element.clientWidth, scrollWidth: element.scrollWidth, whiteSpace: getComputedStyle(element).whiteSpace,
        textRects: Array.from(range.getClientRects(), value => ({ x: value.x, y: value.y, width: value.width, height: value.height })) };
    });
  }
  await writeFile(`${shots}/${locale}/${name}-${width}.json`, JSON.stringify({ viewport: page.viewportSize(), main, controls }, null, 2));
}

/** Visibility assertions alone do not prove an action can be discovered without scrolling. */
async function expectInFirstMainScreen(page: Page, action: Locator) {
  await expect(action).toBeVisible();
  const [main, button] = await Promise.all([page.getByRole('main').boundingBox(), action.boundingBox()]);
  expect(main).not.toBeNull(); expect(button).not.toBeNull();
  expect(await page.getByRole('main').evaluate(element => element.scrollTop)).toBe(0);
  expect(button!.y).toBeGreaterThanOrEqual(main!.y);
  expect(button!.y + button!.height).toBeLessThanOrEqual(main!.y + main!.height);
}

/**
 * Metadata lookup comes first on an existing-Album review: the summary's Look up button is in the first main screen, and the paid
 * Luna AI button follows it, above the first track title, without the class that styles the draft's Save as the primary action
 * (production builds hash class names, so the two buttons' class lists are compared).
 */
async function expectLookupFirst(page: Page) {
  const submit = page.getByRole('region', { name: label('admin.catalog_review.lookup_title'), exact: true }).getByRole('button', { name: label('admin.lookup.submit'), exact: true });
  await expectInFirstMainScreen(page, submit);
  const start = page.getByRole('button', { name: label('admin.catalog_review.analysis_confirm'), exact: true });
  const firstTrack = page.getByRole('textbox', { name: `1 · ${label('admin.field.title')}`, exact: true });
  const [submitBox, startBox, trackBox] = await Promise.all([submit.boundingBox(), start.boundingBox(), firstTrack.boundingBox()]);
  expect(startBox!.y).toBeGreaterThan(submitBox!.y);
  expect(startBox!.y).toBeLessThan(trackBox!.y);
  const classes = async (button: Locator) => (await button.getAttribute('class') ?? '').split(/\s+/).filter(Boolean);
  const luna = await classes(start), save = await classes(page.getByRole('button', { name: label('admin.catalog_review.save_draft'), exact: true }));
  expect(save.filter(name => !luna.includes(name))).not.toEqual([]);
  return start;
}

function titleChangeName(target: string) {
  return label('admin.catalog_review.select_field', { type: label('admin.catalog_review.target_album'), target, field: label('admin.field.title') });
}

/** The final confirmation must display the exact selected original and saved values. */
async function expectFrozenTitle(dialog: Locator, target: string, value: string) {
  const summary = dialog.getByRole('heading', { name: titleChangeName(target), exact: true }).locator('..');
  await expect(summary.getByText(label('admin.catalog_review.original_value'), { exact: true })).toBeVisible();
  await expect(summary.getByText(label('admin.catalog_review.saved_value'), { exact: true })).toBeVisible();
  await expect(summary.getByText(target, { exact: true })).toBeVisible();
  await expect(summary.getByText(value, { exact: true })).toBeVisible();
}

/** Direct catalog approval compares each frozen field without searching unrelated page text. */
async function expectManualChange(dialog: Locator, field: keyof typeof english, current: string, next: string) {
  const article = dialog.getByRole('article').filter({ has: dialog.page().getByRole('heading', { name: label(field), exact: true }) });
  await expect(article).toHaveCount(1);
  const oldValue = article.getByText(label('admin.catalog.current_value'), { exact: true }).locator('..');
  const newValue = article.getByText(label('admin.catalog_review.saved_value'), { exact: true }).locator('..');
  await expect(oldValue.getByText(current, { exact: true })).toBeVisible();
  await expect(newValue.getByText(next, { exact: true })).toBeVisible();
  return { article, oldValue, newValue };
}

async function editManualAlbum(page: Page, title: string) {
  await page.getByRole('textbox', { name: label('admin.field.title'), exact: true }).fill(title);
  for (const [part, value] of [['year', '2026'], ['month', '10'], ['day', '14']] as const) {
    await page.getByRole('spinbutton', { name: label(`admin.field.${part}`), exact: true }).fill(value);
  }
  await page.getByRole('combobox', { name: label('admin.field.visibility'), exact: true }).selectOption('hidden');
}

/** Long confirmations start at the first difference, while their footer remains independently scrollable. */
async function captureManualDialog(page: Page, dialog: Locator, name: string, width: number) {
  const geometry = await dialog.evaluate(element => ({ scrollTop: element.scrollTop, scrollHeight: element.scrollHeight,
    clientHeight: element.clientHeight, initialFocusIsDialog: document.activeElement === element }));
  expect(geometry.scrollTop).toBe(0);
  expect(geometry.initialFocusIsDialog).toBe(true);
  await expect(dialog.getByRole('heading', { name: label('admin.catalog.confirm'), exact: true })).toBeInViewport();
  const first = dialog.getByRole('article').first();
  await expect(first.getByRole('heading', { name: label('admin.field.title'), exact: true })).toBeInViewport();
  await expect(first.getByText(label('admin.catalog.current_value'), { exact: true })).toBeInViewport();
  await expect(first.getByText(label('admin.catalog_review.saved_value'), { exact: true })).toBeInViewport();
  await capture(page, name, width, false, false);
  await writeFile(`${shots}/${locale}/${name}-${width}.json`, JSON.stringify(geometry, null, 2));
  return geometry;
}
async function reflow(page: Page) {
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth && document.body.scrollWidth <= window.innerWidth)).toBe(true);
  expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
}

async function expectDecodedPrivateCover(image: Locator, kind: Exclude<CatalogKind, 'organization'> = 'album') {
  await expect(image).toBeVisible();
  await image.evaluate(element => (element as HTMLImageElement).decode());
  const evidence = await image.evaluate(element => {
    const value = element as HTMLImageElement, rect = value.getBoundingClientRect(), frame = value.parentElement!.getBoundingClientRect(), url = new URL(value.src);
    return { width: rect.width, height: rect.height, naturalWidth: value.naturalWidth, naturalHeight: value.naturalHeight,
      frameWidth: frame.width, frameHeight: frame.height,
      path: url.pathname, viewer: url.searchParams.get('viewer'), origin: url.origin, srcset: value.getAttribute('srcset') };
  });
  expect(evidence.naturalWidth).toBe(640); expect(evidence.naturalHeight).toBe(640);
  expect(evidence.width).toBeGreaterThan(32); expect(Math.abs(evidence.width - evidence.height)).toBeLessThan(1);
  expect(Math.abs(evidence.frameWidth - evidence.frameHeight)).toBeLessThan(1);
  expect(evidence.path).toMatch(new RegExp(`^/api/admin/v1/catalog/${kind}/[a-f0-9]{24}/artwork$`));
  expect(evidence.viewer).toBe(viewer); expect(evidence.origin).toBe(new URL(image.page().url()).origin); expect(evidence.srcset).toBeNull();
  return evidence;
}

function catalogItemName(item: CatalogItem) { return 'name' in item.fields ? item.fields.name : item.fields.title; }
function catalogCategoryLabel(kind: RemainingCatalogKind) { return label(kind === 'audioTrack' ? 'admin.catalog.track' : `admin.catalog.${kind}`); }
function catalogArtworkLabel(item: CatalogItem) {
  const name = catalogItemName(item);
  return item.kind === 'artist' ? label('content.artist.portrait_alt', { name }) : label('content.album.cover_alt', { title: name });
}

/** Organization identity uses the ordinary catalog's decorative name initial, never a fabricated cover URL. */
async function expectOrganizationMark(owner: Locator, name: string) {
  const mark = owner.locator('[aria-hidden="true"]').filter({ hasText: new RegExp(`^${Array.from(name.trim())[0].toUpperCase()}$`) });
  await expect(mark).toHaveCount(1); await expect(mark).toBeVisible();
  const box = await mark.boundingBox(); expect(box).not.toBeNull();
  expect(Math.abs(box!.width - box!.height)).toBeLessThan(1); expect(box!.width).toBeGreaterThan(32);
  await expect(owner.locator('img')).toHaveCount(0);
  return box!;
}

