/** The Album's two members as an Album completion pairs them: ready audio tracks, the second without a Track Number. */
const completionAlbumTracks = (): CatalogAlbumTracks => ({ albumId, order: 'declared', truncated: false, skipped: 0, expected: null, tracks: [
  { position: 1, id: '3'.repeat(24), title: 'Synthetic first track', discNumber: null, trackNumber: 1, duration: '03:05', mediaType: 'audio', visibility: 'public', state: 'ready', linkedElsewhere: false },
  { position: 2, id: '4'.repeat(24), title: 'Synthetic second track', discNumber: null, trackNumber: null, duration: '03:20', mediaType: 'audio', visibility: 'public', state: 'ready', linkedElsewhere: false }] });
/** The release the completion's automatic run applies, whose track paired with the first member credits only a placeholder. */
function placeholderMemberLookup(): ReviewLookupResponse['lookup'] {
  const lookup = reviewLookupResponse().lookup!, member = `tracks.${slotId}.artists`;
  return { ...lookup, applied: { ...lookup.applied!, conflicts: lookup.applied!.conflicts.filter(conflict => conflict.path !== member),
    flagged: [...lookup.applied!.flagged, { path: member, reason: 'placeholder' }] }, needsAnswer: { tie: false, conflicts: lookup.needsAnswer.conflicts.filter(path => path !== member) } };
}

