/** The pairing review (members titled "1-01 …" and "1-02 …" without numbers) as its submitted run left it: no Luna run or suggestion. */
function quietPairingReview(): CatalogReview {
  const item = pairingReview();
  return { ...item, analysis: { ...item.analysis, state: 'idle', generation: 0, operationId: null, completedChunks: 0, totalChunks: 0, attemptsUsed: 0 }, suggestions: [] };
}
/**
 * The server side of the pairing review: a save that gives both members a Track Number re-ranks the run to its paired view, keeping
 * what the run applied; choosing a release writes its label and date and, once the run has a group (a single pairing), also its
 * expected tracklist and the paired members' numbers (pairingApplication).
 */
function pairingServer(api: Awaited<ReturnType<typeof setup>>) {
  api.rerank((draft, current) => draft.tracks.every(track => track.trackNumber !== null) ? pairedLookupResponse(current?.applied ?? null).lookup : undefined);
  api.choose((key, current, item) => {
    if (!key) return undefined;
    const paired = current.groups.length > 0;
    const album = { ...item.draft.album, label: { name: 'Synthetic Live Label', musicBrainzId: null }, releaseDate: { year: 2023, month: 3, day: 29 } };
    return { lookup: { ...current, applied: pairingApplication(key, paired) }, draft: { ...item.draft, album: paired ? { ...album, expectedTracklist: pairingRows() } : album } };
  });
}
/** The pairing review whose titles carry no positions (unnumberedPairingReview), as its submitted run left it: no Luna run or suggestion. */
function quietUnnumberedReview(): CatalogReview {
  const item = unnumberedPairingReview();
  return { ...item, analysis: { ...item.analysis, state: 'idle', generation: 0, operationId: null, completedChunks: 0, totalChunks: 0, attemptsUsed: 0 }, suggestions: [] };
}
/** pairingServer for the live release's 12 + 8 rows (handPairingRows): a choice through the single pairing writes those as the expected tracklist. */
function handPairingServer(api: Awaited<ReturnType<typeof setup>>) {
  pairingServer(api);
  api.choose((key, current, item) => {
    if (!key) return undefined;
    const paired = current.groups.length > 0;
    const album = { ...item.draft.album, label: { name: 'Synthetic Live Label', musicBrainzId: null }, releaseDate: { year: 2023, month: 3, day: 29 } };
    return { lookup: { ...current, applied: pairingApplication(key, paired) }, draft: { ...item.draft, album: paired
      ? { ...album, expectedTracklist: handPairingRows().map(row => ({ discNumber: row.disc, trackNumber: row.track, title: row.title, durationMs: row.durationMs })) } : album } };
  });
}
/** The members' Disc and Track Number inputs in Edit draft, in Album order. */
const numberInputs = (page: Page) => [1, 2].flatMap(position => (['admin.field.disc_number', 'admin.field.track_number'] as const)
  .map(field => page.getByRole('spinbutton', { name: `${position} · ${label(field)}`, exact: true })));
/** The only changes a save sends after filling from "1-01 " and "1-02 ": both members' Disc and Track Numbers, each over none. */
const filledChanges = () => [slotId, slotTwo].flatMap((slot, index) => [{ path: `tracks.${slot}.discNumber`, base: null, value: 1 },
  { path: `tracks.${slot}.trackNumber`, base: null, value: index + 1 }]);
/** A control's classes; production builds hash class names, so a primary button is told by sharing Save completion draft's. */
const classList = async (element: Locator) => (await element.getAttribute('class') ?? '').split(/\s+/).filter(Boolean);

